def metric(count, pixels=1000, sharp=10, valid=True):
    return {"status":"available" if valid else "unavailable","count":count,"coverage":count/1000,
      "analysis_pixels":pixels,"has_evidence":bool(count),"quality":{"eligible":valid,"tier":2,"sharpness":sharp}}
def test_primary_per_detector_and_no_sum():
    views={}
    for view in ("left","front","right"):
        views[view]={"modules":{}}
        for module in ("acne","pores"):
            m=metric(9 if view=="left" else 0)
            views[view]["modules"][module]={"regions":{"nose":m}}
    views["front"]["modules"]["pores"]["regions"]["nose"]=metric(0,valid=False)
    chosen=select_primary(views)
    acne=chosen["regions"]["nose"]["modules"]["acne"]
    pores=chosen["regions"]["nose"]["modules"]["pores"]
    assert acne["primary_view"]=="front" and acne["metrics"]["count"]==0
    assert acne["statement"]=="主视角未检出；补充视角有发现"
    assert pores["primary_view"]=="left"
    assert chosen["whole_face_unique_count"] is None
    assert not chosen["cross_view_lesion_deduplication"]

