 ("left",{"nose":7,"right_cheek":531}),
 ("front",{"forehead":802,"nose":210,"right_cheek":250,"left_cheek":263}),
 ("right",{"nose":2,"left_cheek":551})])
def test_saved_pores_same_image_native_regions(view,expected):
 data=json.loads((CASE/"水光检测完整结果.json").read_text(encoding="utf-8"));v=data["views"][view];item=v["modules"]["pores"]
 with np.load(CASE/v["geometry"]) as g:skin=g["skin_mask"].copy();points=g["landmarks"].copy();observed=g["observed_skin_mask"].copy();hair=g["hair_mask"].copy()
 with np.load(CASE/item["evidence"]) as e:evidence={k:e[k].copy() for k in ("mask","response","valid_mask")}
 image=cv2.imdecode(np.fromfile(CASE/v["input"],np.uint8),cv2.IMREAD_COLOR)
 image=cv2.warpAffine(image,np.float32(v["transform"]),(1024,1024))
 a,policy,radius=measurement_partition("pores",image,skin,points,v["quality"]["flags"],evidence["valid_mask"],observed,view,hair)
 assert policy=="v2_detector_regions_subject_sides" and radius==0
 stats=module_observations(data["capture_id"],view,"pores",item,evidence,a,points,image,v["quality"]["flags"],boundary_radius=radius)
 assert not stats["rejected_observations"] and not stats["uncertain_observations"]
 for region,n in expected.items():
  m=stats["regions"][region];assert m["count"]==n
  domain=(a.labels==LEAVES.index(region)+1)&(evidence["valid_mask"]>0)
  assert m["analysis_pixels"]==int(domain.sum())
  assert m["density_per_100k_pixels"]==n*100000/int(domain.sum())
  assert m["coverage"]==np.count_nonzero((evidence["mask"]>0)&domain)/int(domain.sum())
 assert sum(x["count"] or 0 for x in stats["regions"].values())==len(item["instances"])
 assert not [x for x in stats["observations"] if x["region_id"]=="chin"]
 for x in stats["observations"]:
  px,py=np.rint(x["centroid"]).astype(int);assert a.labels[py,px]>0 and evidence["valid_mask"][py,px]>0
 if view=="left":
  face=partition(points,observed,view,hair,for_statistics=True)
  for i in [18,36,40,43,51,62]:
   x=next(p for p in item["instances"] if p["id"]==i);px,py=np.rint(x["centroid"]).astype(int)
   assert face.face[py,px]>0
`;
