import json,hashlib,shutil,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from shuiguang.regional_package import enrich_result
from shuiguang.render import rebuild
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def run(rel):
 root=ROOT/"outputs"/rel;before=json.loads((root/"水光检测完整结果.json").read_text(encoding="utf-8"))
 oldstats=json.loads((root/"区域统计V2.json").read_text(encoding="utf-8"))
 backup=ROOT/"runtime/region_v22_backups"/rel.replace("/","__")
 if not backup.exists():
  backup.mkdir(parents=True)
  for p in root.rglob("*"):
   if p.is_file() and (p.suffix in (".json",".html",".js",".css") or "06_面部问题地图" in p.parts):
    dest=backup/p.relative_to(root);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest)
 protected={}
 for v in before["views"].values():
  for k in ("input","geometry"):
   if v.get(k):protected[v[k]]=sha(root/v[k])
  for item in v.get("modules",{}).values():
   for key in ("mask","evidence","valid_mask","overlay_layer"):
    if item.get(key):protected[item[key]]=sha(root/item[key])
 presentation=json.loads((root/"V2结果图索引.json").read_text(encoding="utf-8"))
 for v in presentation["views"].values():
  for item in v["modules"].values():
   for key in ("base","result","display_scope"):
    if item.get(key):protected[item[key]]=sha(root/item[key])
 stats,_=enrich_result(root);rebuild(root)
 after=json.loads((root/"水光检测完整结果.json").read_text(encoding="utf-8"))
 assert all(sha(root/name)==value for name,value in protected.items())
 diffs=[];items=0
 for view,v in before["views"].items():
  for module,m in v.get("modules",{}).items():
   if m.get("status")!="success":continue
   new=after["views"][view]["modules"][module]
   assert m["metrics"]==new["metrics"]
   assert [(i["id"],i["centroid"],i["original_centroid"]) for i in m["instances"]]==[(i["id"],i["centroid"],i["original_centroid"]) for i in new["instances"]]
   account=stats["display_reconciliation"]["modules"][module]["views"][view]
   assert account["total_count"]==account["listed_count"]+account["unlisted_count"]==len(m["instances"])
   for reg,row in stats["views"][view]["modules"][module]["regions"].items():
    old=oldstats["views"][view]["modules"][module]["regions"].get(reg,{})
    if old.get("count")!=row.get("count"):diffs.append({"view":view,"module":module,"region":reg,"before":old.get("count"),"after":row.get("count")})
   items+=1
 result={"capture":rel,"items":items,"protected_artifacts":len(protected),"detector_outputs_and_centres_unchanged":True,"changes":diffs,"statistics_version":stats["version"]}
 (root/"分区统计修复回执.json").write_text(json.dumps(result,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
 print(json.dumps({"capture":rel,"items":items,"protected":len(protected),"pores":stats["display_reconciliation"]["modules"]["pores"]},ensure_ascii=False),flush=True)
 return result
if __name__=="__main__":
 results=[run(x) for x in sys.argv[1:]]
 (ROOT/"qa/region_v22_repair.json").write_text(json.dumps(results,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
`;
